import { projectScripts } from "./projectScripts";
export type BuildVisual = {
  id: string;
  title: string;
  caption: string;
  provenance: "Illustrative" | "Measured";
  labels: string[];
};

export type ProjectCodeStage = {
  title: string;
  why: string;
  code: string;
};

export type BuildProject = {
  id: string;
  title: string;
  task: "Regression" | "Binary classification" | "Multiclass classification";
  status: "Supplemental" | "PDF-derived" | "PDF-derived + supplemental use case";
  sourcePages?: string;
  problem: string;
  stakeholder: string;
  target: string;
  metric: string;
  dataProvenance: string;
  schema: { field: string; type: string; meaning: string }[];
  sampleRecord: string[];
  baseline: string;
  modelRationale: string;
  split: string;
  fitBoundary: string;
  architecture: string[];
  shapes: { name: string; shape: string; meaning: string }[];
  codeStages: ProjectCodeStage[];
  fullScriptPath: string;
  fullScript?: string;
  testPath: string;
  runInstructions: string;
  optionalDownloads: string;
  expected: string[];
  metrics: string[];
  visuals: BuildVisual[];
  pitfalls: string[];
  extensions: string[];
  questions: { question: string; answer: string }[];
  lessonIds: string[];
  recipeIds: string[];
};

const sharedVisual = (id: string, title: string, caption: string, labels: string[]): BuildVisual => ({ id, title, caption, provenance: "Illustrative", labels });
const commonQuestions = [
  { question: "Why keep the test split out of repeated model choices?", answer: "Repeatedly using test results to choose features, thresholds, epochs, or architecture leaks test information into the process. Tune on validation data and evaluate the test set once for a final estimate." },
  { question: "What does a smoke test establish?", answer: "It checks executable contracts such as finite loss, tensor shapes, and an optimizer step. It does not establish useful generalization or a benchmark score." },
  { question: "Why report provenance for a plot?", answer: "A reader needs to know whether values came from a fixed teaching illustration or a reproducible model run before interpreting the graph as evidence." },
];

