for (const project of buildProjects) {
  project.fullScript = projectScripts[project.id];
  project.codeStages.push(...closingStages[project.id]);
}

export const projectById = new Map(buildProjects.map((project) => [project.id, project]));
export const projectSearchText = (project: BuildProject) => [project.title, project.task, project.problem, project.target, project.dataProvenance, ...project.schema.map((field) => `${field.field} ${field.meaning}`), ...project.lessonIds].join(" ").toLowerCase();

export function validateBuildProjects(projects: BuildProject[]) {
  const ids = new Set<string>();
  const issues: string[] = [];
  for (const p of projects) {
    if (ids.has(p.id)) issues.push(`${p.id}: duplicate project id`);
    ids.add(p.id);
    for (const [field, value] of Object.entries({problem:p.problem,stakeholder:p.stakeholder,target:p.target,dataProvenance:p.dataProvenance,baseline:p.baseline,modelRationale:p.modelRationale,split:p.split,fitBoundary:p.fitBoundary,fullScriptPath:p.fullScriptPath,testPath:p.testPath,runInstructions:p.runInstructions})) if (!value?.trim()) issues.push(`${p.id}: missing ${field}`);
    if (p.visuals.length < 3) issues.push(`${p.id}: needs at least three visuals`);
    if (p.visuals.some((v) => !v.title || !v.caption || !v.labels.length || !v.provenance)) issues.push(`${p.id}: incomplete visual metadata`);
    if (p.codeStages.length < 4) issues.push(`${p.id}: needs staged code`);
    if (!p.lessonIds.length || !p.recipeIds.length) issues.push(`${p.id}: needs lesson and Field Kit links`);
  }
  return issues;
}
